4	
5	/**
6	 * A simple model of a mouse.
7	 * Mice age, move, eat grass, breed, and die.
8	 *
9	 * @version 2022.03.02
10	 */
11	public class Mouse extends Animal
12	{
13	    // Characteristics shared by all mice (class variables).
14	    private static final int BREEDING_AGE = 5;
15	    private static final int MAX_AGE = 125;
16	    private static final double BREEDING_PROBABILITY = 0.25;
17	    private static final double INFECT_PROBABILITY = 0.01;
18	    private static final int MAX_LITTER_SIZE = 10;
19	    private static final int DEFAULT_FOOD_LEVEL = 5;
20	    private static final Random rand = Randomizer.getRandom();
21	    private static final int FOOD_VALUE = 5;
22	    private static final double RECOVER_PROBABILITY = 0.3;
23	    private static final double DETERIORATE_PROBABILITY = 0.15;
24	
25	    // Individual characteristics (instance fields).
26	    private int foodLevel;
27	    // Infection level: 0 = healthy, 1-3 = infected (dies at 3).
28	    private int infect;
29	
30	    /**
31	     * Create a new mouse. A mouse may be created with age
32	     * zero (a new born) or with a random age.
33	     *
34	     * @param randomAge If true, the mouse will have a random age.
35	     * @param field The field currently occupied.
36	     * @param location The location within the field.
37	     */
38	    public Mouse(boolean randomAge, Field<Entity> field, Location location)
39	    {
40	        super(field, location);
41	        if (randomAge) {
42	            age = rand.nextInt(MAX_AGE);
43	            foodLevel = rand.nextInt(DEFAULT_FOOD_LEVEL);
44	        } else {
45	            foodLevel = DEFAULT_FOOD_LEVEL;
46	        }
47	    }
48	
49	    @Override protected int getMaxAge()                      { return MAX_AGE; }
50	    @Override protected int getBreedingAge()                 { return BREEDING_AGE; }
51	    @Override protected double getBreedingProbability()      { return BREEDING_PROBABILITY; }
52	    @Override protected int getMaxLitterSize()               { return MAX_LITTER_SIZE; }
53	    @Override public    int foodValue()                      { return FOOD_VALUE; }
54	
55	    /**
56	     * This is what the mouse does most of the time - it runs
57	     * around. Sometimes it will breed or die of old age.
58	     * @param newMice A list to return newly born mice.
59	     * @param step The current step.
60	     * @param weather The current weather.
61	     */
62	    public void act(List<Entity> newMice, int step, String weather)
63	    {
64	        incrementAge();
65	        updateBurnStatus(weather);
66	        checkInfectLevel();
67	        if (isAlive()) {
68	            if (getInfected() != 0) {
69	                spreadDisease();
70	                diseaseRecover();
71	            } else {
72	                giveBirth(newMice);
73	                tryInfect();
74	            }
75	
76	            Location newLocation = findFood();
77	            if (newLocation == null) {
78	                newLocation = getField().freeAdjacentLocation(getLocation());
79	            }
80	            if (newLocation != null) {
81	                setLocation(newLocation);
82	            } else {
83	                setDead();
84	            }
85	        }
86	    }
87	
88	    /**
89	     * Check whether or not this mouse is to give birth at this step.
90	     * New births will be made into free adjacent locations.
91	     * @param newMice A list to return newly born mice.
92	     */
93	    private void giveBirth(List<Entity> newMice)
94	    {
95	        Field<Entity> field = getField();
96	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
97	        int births = breed();
98	        for (int b = 0; b < births && free.size() > 0; b++) {
99	            Location loc = free.remove(0);
100	            newMice.add(new Mouse(false, field, loc));
101	        }
102	    }
103	
104	    /**
105	     * Look for grass adjacent to the current location.
106	     * @return Where food was found, or null if it wasn't.
107	     */
108	    private Location findFood()
109	    {
